<template>
  <div class="min-h-screen px-4 py-8 sm:px-6 lg:px-8"><div class="mx-auto max-w-7xl space-y-6">
    <PageHeader :title="t('admin_billing.topups_title')" :description="t('admin_billing.topups_desc')"><button class="inline-flex items-center gap-2 rounded-xl bg-cyan-600 px-4 py-2.5 text-sm font-bold text-white" @click="openCreate"><span class="material-symbols-outlined text-lg">add</span>{{ t('admin_billing.create_topup') }}</button></PageHeader>
    <div class="rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-white/10 dark:bg-white/5">
      <form class="grid gap-3 border-b border-slate-200 p-4 sm:grid-cols-2 lg:grid-cols-5 dark:border-white/10" @submit.prevent="applyFilters"><input v-model.trim="filters.search" class="billing-input lg:col-span-2" :placeholder="t('admin_billing.search_plan')" /><select v-model="filters.is_sellable" class="billing-input"><option value="">{{ t('admin_billing.all_sale_statuses') }}</option><option value="1">{{ t('admin_billing.sellable') }}</option><option value="0">{{ t('admin_billing.not_sellable') }}</option></select><select v-model="filters.is_visible" class="billing-input"><option value="">{{ t('admin_billing.all_visibility') }}</option><option value="1">{{ t('admin_billing.visible') }}</option><option value="0">{{ t('admin_billing.hidden') }}</option></select><button class="rounded-xl bg-slate-900 px-4 py-2.5 text-sm font-bold text-white dark:bg-white dark:text-slate-900">{{ t('admin_billing.filter') }}</button></form>
      <PageState :loading="loading" :error="error" :empty="!items.length" :empty-text="t('admin_billing.no_topups')" @retry="load"><div class="overflow-x-auto"><table class="min-w-[900px] w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500 dark:bg-black/20 dark:text-slate-400"><tr><th class="p-4">{{ t('admin_billing.header_plan') }}</th><th class="p-4">{{ t('admin_billing.header_price') }}</th><th class="p-4">{{ t('admin_billing.header_token') }}</th><th class="p-4">{{ t('admin_billing.header_status') }}</th><th class="p-4">{{ t('admin_billing.header_order') }}</th><th class="p-4">{{ t('admin_billing.header_updated') }}</th><th class="p-4 text-right">{{ t('admin_billing.header_actions') }}</th></tr></thead><tbody class="divide-y divide-slate-100 dark:divide-white/5"><tr v-for="item in items" :key="item.id"><td class="p-4"><p class="font-extrabold dark:text-white">{{ item.name }}</p><code class="text-xs text-cyan-700 dark:text-cyan-300">{{ item.code }}</code></td><td class="p-4 font-bold">{{ formatBillingMoney(item.price, item.currency) }}</td><td class="p-4 font-bold">{{ formatBillingNumber(item.token_amount) }}</td><td class="p-4"><div class="flex flex-col items-start gap-1"><StatusBadge :status="item.is_sellable ? 'sellable' : 'not_sellable'" :label="item.is_sellable ? t('admin_billing.sellable') : t('admin_billing.not_sellable')"/><StatusBadge :status="item.is_visible ? 'visible' : 'hidden'" :label="item.is_visible ? t('admin_billing.visible') : t('admin_billing.hidden')"/></div></td><td class="p-4">{{ item.sort_order }}</td><td class="p-4">{{ formatBillingDate(item.updated_at, true) }}</td><td class="p-4"><div class="flex justify-end gap-2"><button class="icon-button" :title="t('admin_billing.edit')" @click="openEdit(item)"><span class="material-symbols-outlined text-lg">edit</span></button><button class="icon-button" :title="t('admin_billing.status_action')" @click="openStatus(item)"><span class="material-symbols-outlined text-lg">toggle_on</span></button></div></td></tr></tbody></table></div><Pagination :pagination="pagination" @change="changePage" /></PageState>
    </div>
    <TopupFormModal v-model="formOpen" :item="selected" :busy="saving" :server-errors="fieldErrors" @submit="save" />
    <CatalogStatusModal v-if="selected" v-model="statusOpen" kind="topup" :item-name="selected.name" :initial-sellable="selected.is_sellable" :initial-visible="selected.is_visible" :busy="saving" :server-errors="fieldErrors" @submit="saveStatus" />
  </div></div>
</template>

<script setup lang="ts">
import type { BillingPagination, BillingTopupPackage, FieldErrors } from '~/types/admin-billing'
import PageHeader from '~/components/admin/billing/PageHeader.vue'; import PageState from '~/components/admin/billing/PageState.vue'; import Pagination from '~/components/admin/billing/Pagination.vue'; import StatusBadge from '~/components/admin/billing/StatusBadge.vue'; import TopupFormModal from '~/components/admin/billing/TopupFormModal.vue'; import CatalogStatusModal from '~/components/admin/billing/CatalogStatusModal.vue'; import { formatBillingDate, formatBillingMoney, formatBillingNumber } from '~/utils/adminBilling'
definePageMeta({ layout: 'layout-admin' })
const { t } = useI18n()
const api = useAdminBilling(); const toast = useToast(); const items = ref<BillingTopupPackage[]>([]); const pagination = ref<BillingPagination>({ current_page: 1, per_page: 20, total: 0, last_page: 1 }); const filters = reactive({ search: '', is_sellable: '', is_visible: '', page: 1, per_page: 20 }); const loading = ref(true); const saving = ref(false); const error = ref(''); const fieldErrors = ref<FieldErrors>({}); const formOpen = ref(false); const statusOpen = ref(false); const selected = ref<BillingTopupPackage | null>(null)
const load = async () => { loading.value = true; error.value = ''; try { const response = await api.listTopupPackages(filters); items.value = response.data; pagination.value = response.pagination } catch (e) { error.value = getAdminBillingErrorMessage(e) } finally { loading.value = false } }
const applyFilters = () => { filters.page = 1; load() }; const changePage = (page: number) => { filters.page = page; load() }; const openCreate = () => { selected.value = null; fieldErrors.value = {}; formOpen.value = true }; const openEdit = async (item: BillingTopupPackage) => { fieldErrors.value = {}; try { selected.value = (await api.getTopupPackage(item.id)).data; formOpen.value = true } catch (e) { toast.error(getAdminBillingErrorMessage(e)) } }; const openStatus = (item: BillingTopupPackage) => { selected.value = item; fieldErrors.value = {}; statusOpen.value = true }
const save = async (payload: Record<string, unknown>) => { if (saving.value) return; saving.value = true; fieldErrors.value = {}; try { if (selected.value) await api.updateTopupPackage(selected.value.id, payload); else await api.createTopupPackage(payload); toast.success(selected.value ? t('admin_billing.topup_updated') : t('admin_billing.topup_created')); formOpen.value = false; await load() } catch (e) { if (e instanceof AdminBillingError) fieldErrors.value = e.errors; toast.error(getAdminBillingErrorMessage(e)) } finally { saving.value = false } }
const saveStatus = async (payload: Record<string, unknown>) => { if (!selected.value || saving.value) return; saving.value = true; fieldErrors.value = {}; try { await api.updateTopupPackageStatus(selected.value.id, payload); toast.success(t('admin_billing.topup_status_updated')); statusOpen.value = false; await load() } catch (e) { if (e instanceof AdminBillingError) fieldErrors.value = e.errors; toast.error(getAdminBillingErrorMessage(e)) } finally { saving.value = false } }
onMounted(load)
</script>
<style scoped>.billing-input{ @apply w-full rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 text-sm outline-none focus:border-cyan-500 dark:border-white/10 dark:bg-black/20 dark:text-white; }.icon-button{ @apply rounded-lg border border-slate-200 p-2 text-slate-600 hover:border-cyan-400 hover:text-cyan-600 dark:border-white/10 dark:text-slate-300; }</style>
